-- Photos Wikimedia Commons vérifiées une à une (le fichier représente ce plat), auteur et licence conservés.
-- Troisième passe (catégories « Cuisine of <pays> » parcourues sur deux niveaux) : 16 recettes des lots, 3 recettes plus anciennes.
-- N'ajoute une photo qu'aux recettes publiées qui n'en ont pas encore : relancer ne duplique rien.
insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
  photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
select r.id, 'external_licensed', 'ready', e->>'url', r.title, 'Wikimedia Commons', e->>'page',
  nullif(e->>'author', ''), e->>'license', nullif(e->>'licenseUrl', ''),
  'Photo : ' || coalesce(nullif(e->>'author', ''), 'auteur inconnu') || ' · ' || (e->>'license') || ' · Wikimedia Commons',
  true, true, 'Photo Wikimedia Commons vérifiée : le fichier représente ce plat.'
from jsonb_array_elements($photos$[{"slug":"jareesh-najdi","url":"https://upload.wikimedia.org/wikipedia/commons/e/e5/%D8%A7%D9%84%D8%AC%D8%B1%D9%8A%D8%B4.jpg","page":"https://commons.wikimedia.org/wiki/File:%D8%A7%D9%84%D8%AC%D8%B1%D9%8A%D8%B4.jpg","author":"Tmogarry","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"cazuela-chilena","url":"https://upload.wikimedia.org/wikipedia/commons/0/0e/Cazuela_de_ave.jpg","page":"https://commons.wikimedia.org/wiki/File:Cazuela_de_ave.jpg","author":"Marieloreto","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en"},{"slug":"moros-y-cristianos","url":"https://upload.wikimedia.org/wikipedia/commons/2/21/Cuban_cuisine.jpg","page":"https://commons.wikimedia.org/wiki/File:Cuban_cuisine.jpg","author":"George Kelly","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},{"slug":"garba-d-abidjan","url":"https://upload.wikimedia.org/wikipedia/commons/f/f3/Garba_%C3%A0_bouak%C3%A9_1.jpg","page":"https://commons.wikimedia.org/wiki/File:Garba_%C3%A0_bouak%C3%A9_1.jpg","author":"Kod B","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"lovo-fidji","url":"https://upload.wikimedia.org/wikipedia/commons/7/71/Lovo.jpg","page":"https://commons.wikimedia.org/wiki/File:Lovo.jpg","author":"Jaejay77","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"id":"ab5e72b2-6501-452e-b6ce-2dfb807ef445","url":"https://upload.wikimedia.org/wikipedia/commons/5/5f/Kokodafood.jpg","page":"https://commons.wikimedia.org/wiki/File:Kokodafood.jpg","author":"yuko_ppp2501","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},{"id":"73da83dd-db71-4cbd-99e9-336910b4fa39","url":"https://upload.wikimedia.org/wikipedia/commons/8/8f/Griot_ha%C3%AFtien.jpg","page":"https://commons.wikimedia.org/wiki/File:Griot_ha%C3%AFtien.jpg","author":"Lëa-Kim Châteauneuf","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"oromo-kirghiz","url":"https://upload.wikimedia.org/wikipedia/commons/e/e5/Oromo_%28dish%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Oromo_(dish).jpg","author":"Абдырашит Сатылганов","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0"},{"slug":"mok-pa-lao","url":"https://upload.wikimedia.org/wikipedia/commons/8/87/Fish_with_coconut_milk_served_in_banana_leaf.jpg","page":"https://commons.wikimedia.org/wiki/File:Fish_with_coconut_milk_served_in_banana_leaf.jpg","author":"mick62","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"},{"slug":"ohridska-pastrmka","url":"https://upload.wikimedia.org/wikipedia/commons/c/c3/%D0%9E%D1%85%D1%80%D0%B8%D0%B4%D1%81%D0%BA%D0%B0_%D0%BF%D0%B0%D1%81%D1%82%D1%80%D0%BC%D0%BA%D0%B0_.jpg","page":"https://commons.wikimedia.org/wiki/File:%D0%9E%D1%85%D1%80%D0%B8%D0%B4%D1%81%D0%BA%D0%B0_%D0%BF%D0%B0%D1%81%D1%82%D1%80%D0%BC%D0%BA%D0%B0_.jpg","author":"Ivonatk","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"mishkak-omanais","url":"https://upload.wikimedia.org/wikipedia/commons/7/7e/%D8%A7%D9%84%D9%85%D8%B4%D8%A7%D9%83%D9%8A%D9%83_%D8%A7%D9%84%D8%B9%D9%85%D8%A7%D9%86%D9%8A%D8%A9.jpg","page":"https://commons.wikimedia.org/wiki/File:%D8%A7%D9%84%D9%85%D8%B4%D8%A7%D9%83%D9%8A%D9%83_%D8%A7%D9%84%D8%B9%D9%85%D8%A7%D9%86%D9%8A%D8%A9.jpg","author":"Rahill 1485","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"pondu-congolais","url":"https://upload.wikimedia.org/wikipedia/commons/0/05/Saka-saka_-_pounded_and_cooked_cassava_leaves.jpg","page":"https://commons.wikimedia.org/wiki/File:Saka-saka_-_pounded_and_cooked_cassava_leaves.jpg","author":"T.K. Naliaka","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"id":"84031b86-c35c-443e-96dc-26888b73abb3","url":"https://upload.wikimedia.org/wikipedia/commons/8/81/Krashka_jota_half_eaten_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Krashka_jota_half_eaten_01.jpg","author":"Sljehernik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"bara-suriname","url":"https://upload.wikimedia.org/wikipedia/commons/0/0e/Surinamese_bara_in_Rotterdam_%282019%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Surinamese_bara_in_Rotterdam_(2019).jpg","author":"Sebleouf","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"kissar-tchadien","url":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Kissar_%C3%A0_base_du_mil.jpg","page":"https://commons.wikimedia.org/wiki/File:Kissar_%C3%A0_base_du_mil.jpg","author":"YACOUB DOUNGOUS","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"syrnyky-ukrainiens","url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Ukrainian_syrnyky.jpg","page":"https://commons.wikimedia.org/wiki/File:Ukrainian_syrnyky.jpg","author":"Evil linnka","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"},{"slug":"mandi-hadramaout","url":"https://upload.wikimedia.org/wikipedia/commons/f/fe/Mandi.PNG","page":"https://commons.wikimedia.org/wiki/File:Mandi.PNG","author":"w:user:Bamakhrama","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/"},{"slug":"gaat-erythreen","url":"https://upload.wikimedia.org/wikipedia/commons/d/d8/Ga%27at_food.jpg","page":"https://commons.wikimedia.org/wiki/File:Ga%27at_food.jpg","author":"Stefan Alfons Tzeggai","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},{"slug":"gomen-ethiopien","url":"https://upload.wikimedia.org/wikipedia/commons/8/8d/Ayib_and_gomen.jpg","page":"https://commons.wikimedia.org/wiki/File:Ayib_and_gomen.jpg","author":"stu_spivack","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"}]$photos$::jsonb) as e
join public.recipes r on (e ? 'id' and r.id = (e->>'id')::uuid) or (e ? 'slug' and r.slug = e->>'slug')
where r.status = 'published'
  and not exists (select 1 from public.recipe_images i where i.recipe_id = r.id and i.status = 'ready');
